namespace FormatFactoryWinUI.Services;

internal static class ScanPrintLocalizationResources
{
    internal static LocalizedResourceModule Module { get; } = new("ScanPrint", BuildEntries());

    private static IReadOnlyList<LocalizedResourceEntry> BuildEntries()
    {
        return Rows.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Select(row => row.Split('|'))
            .Select(fields => new LocalizedResourceEntry(fields[0], fields.Skip(1).ToArray()))
            .ToArray();
    }

